// spec: specs/talent-onboarding.md §5.3 · case: .qa/tests/talent-onboarding/TO-5-2.md · ticket #a904f9
// Two roles (talent = demo-talent-1 U-13, hunter_free), each in its own window via asUser.
// Changes shared data (profile type of demo-talent-1) → @data; the original state (PUBLIC) is always restored in finally.
// Written by autotest-writer without a live run — confirm the «שמירה» selector on the first /qa-regress.

import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';

const TALENT_PROFILE = '/profile/8a5a5e39-8633-469a-9589-32ece69f54c9';
const TALENT_NAME = 'משה כהן';
const TALENT_HANDLE = '@moshecohen';
const EMPLOYERS = ['Monday', 'Deploy'];
const EMAIL = /[\w.+-]+@[\w-]+\.[\w.]+/;
const PHONE = /05\d-?\d{3}-?\d{4}/;

test.describe.configure({ mode: 'serial' });

async function openPersonalTab(talent: Page) {
  await talent.goto('/profile?edit=personal');
  const tab = talent.getByRole('tab', { name: 'פרטים אישיים' });
  await expect(tab).toBeVisible();
  if ((await tab.getAttribute('aria-selected')) !== 'true') await tab.click();
  await expect(tab).toHaveAttribute('aria-selected', 'true');
}

const radio = (talent: Page, value: 'anonymous' | 'public') =>
  talent.locator(`input[name="profile-visibility"][value="${value}"]`);

async function setProfileType(talent: Page, value: 'anonymous' | 'public') {
  await openPersonalTab(talent);
  await radio(talent, value).check();
  await talent.getByRole('button', { name: 'שמירה' }).click();
  // Saved: reopen the form and see the choice persisted
  await expect(async () => {
    await openPersonalTab(talent);
    await expect(radio(talent, value)).toBeChecked({ timeout: 3000 });
  }).toPass({ timeout: 30_000 });
}

test.describe('Talent profile type after onboarding — #a904f9', () => {
  test('Talent switches anonymous → public: hunter sees personal data hidden / shown @desktop @data #a904f9', async ({ asUser }) => {
    const talent = await asUser('talent');
    const hunter = await asUser('hunter_free');

    // Precondition: demo-talent-1 is public (original state). Otherwise stop — do not "fix" the account.
    await openPersonalTab(talent);
    await expect(talent.locator('input[name="profile-visibility"]')).toHaveCount(2);
    await expect(radio(talent, 'public'), 'demo-talent-1 must start PUBLIC — stop and report, do not change the account').toBeChecked();

    try {
      await test.step('talent switches to «פרופיל אנונימי» and saves', async () => {
        await radio(talent, 'anonymous').check();
        await expect(talent.getByText('בפרופיל אנונימי, התמונה שלכם, כמו גם שאר הפרטים האישיים, לא ייחשפו')).toBeVisible();
        await talent.getByRole('button', { name: 'שמירה' }).click();
        await expect(async () => {
          await openPersonalTab(talent);
          await expect(radio(talent, 'anonymous')).toBeChecked({ timeout: 3000 });
        }).toPass({ timeout: 30_000 });
      });

      await test.step('hunter_free sees an anonymous profile: no name / handle / e-mail / phone / employers / CV', async () => {
        await expect(async () => {
          await hunter.goto(TALENT_PROFILE);
          await expect(hunter.getByText('פרופיל אנונימי', { exact: true })).toBeVisible({ timeout: 5000 });
        }).toPass({ timeout: 30_000 });
        const main = hunter.locator('main');
        await expect(main.getByText(TALENT_NAME)).toHaveCount(0);
        await expect(main.getByText(TALENT_HANDLE)).toHaveCount(0);
        await expect(main).not.toContainText(EMAIL);
        await expect(main).not.toContainText(PHONE);
        for (const employer of EMPLOYERS) await expect(main.getByText(employer, { exact: true })).toHaveCount(0);
        await expect(hunter.getByRole('link', { name: /קו״ח|קו"ח/ })).toHaveCount(0);
        await expect(hunter.locator('a[href*="/storage/v1/object/"]')).toHaveCount(0);
      });

      await test.step('talent switches back to «פרופיל גלוי» and saves', async () => {
        await setProfileType(talent, 'public');
      });

      await test.step('hunter_free sees the public profile: name, e-mail, phone, employers', async () => {
        await expect(async () => {
          await hunter.goto(TALENT_PROFILE);
          await expect(hunter.getByText(TALENT_NAME)).toBeVisible({ timeout: 5000 });
        }).toPass({ timeout: 30_000 });
        const main = hunter.locator('main');
        await expect(main).toContainText(EMAIL);
        await expect(main).toContainText(PHONE);
        for (const employer of EMPLOYERS) await expect(main.getByText(employer, { exact: true }).first()).toBeVisible();
        await expect(hunter.getByText('פרופיל אנונימי', { exact: true })).toHaveCount(0);
      });
    } finally {
      // Cleanup: demo-talent-1 must end PUBLIC (original state).
      await openPersonalTab(talent);
      if (!(await radio(talent, 'public').isChecked())) await setProfileType(talent, 'public');
      await expect(radio(talent, 'public')).toBeChecked();
    }
  });
});
